use crate::{jc097 as b,model::*,unit_support::*};
fn settle(g:&mut Game){for _ in 0..80{if g.pending.is_some()||g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!()}
fn grave(g:&mut Game,id:&str,seat:usize){let c=g.make_card(id,seat);g.players[seat].graveyard.push(c);}
fn revealed(n:usize)->(Game,String,String){let mut g=game();fund(&mut g,0,"JC125",4);for _ in 0..n{grave(&mut g,"JC125",0);}grave(&mut g,"BQ088",0);grave(&mut g,"JC125",1);let target=field(&mut g,"JC125",2);let c=held(&mut g,b::ID,0);reject(&mut g,0,Action{card_id:Some(c.clone()),region:Some(0),..Action::new("deploy")});act(&mut g,0,Action{card_id:Some(c),region:Some(0),..Action::new("conceal")});let c=g.regions[0].cards.iter().find(|c|c.definition==b::ID).unwrap().id.clone();act(&mut g,0,Action{card_id:Some(c.clone()),..Action::new("reveal")});settle(&mut g);let c=g.regions[0].cards.iter().find(|c|c.definition==b::ID).unwrap().id.clone();(g,c,target)}
#[test]fn jc097_catalog_stealth_paid_reveal_and_character_only_count(){assert_current_serial_catalog();assert!(!crate::catalog::card(b::ID).supported);let(mut g,source,target)=revealed(2);let p=g.pending.as_ref().unwrap();assert!(p.choice.options.iter().any(|o|o.id==source));assert!(p.choice.options.iter().any(|o|o.id==target));let ChoiceResolution::Declare{declaration:d,..}=&p.resolution else{panic!()};let crate::rules::Op::JC097Raid{observation:Some(o)}=&d.ability.ops[0]else{panic!()};assert_eq!(o.corpses.len(),2);choose(&mut g,vec![target.clone()]);settle(&mut g);assert!(g.board(&target).is_none());restore(&mut g);}
#[test]fn jc097_zero_damage_and_optional_decline(){for decline in [false,true]{let(mut g,_,target)=revealed(0);choose(&mut g,if decline{vec![]}else{vec![target.clone()]});settle(&mut g);assert!(g.board(&target).is_some());restore(&mut g);}}
#[test]fn jc097_frozen_x_survives_grave_and_source_departure(){let(mut g,source,target)=revealed(2);choose(&mut g,vec![target.clone()]);while !g.players[0].graveyard.is_empty(){let c=g.take_grave_observed(0,0);g.players[0].hand.push(c);}g.return_hand(&source);restore(&mut g);settle(&mut g);assert!(g.board(&target).is_none());}
#[test]fn jc097_response_target_move_and_region_replacement_fizzle(){for replaced in [false,true]{let(mut g,_,target)=revealed(2);choose(&mut g,vec![target.clone()]);if replaced{g.regions[0].card=g.make_card("DQJC115",0);}else{let i=g.regions[0].cards.iter().position(|c|c.id==target).unwrap();let c=g.regions[0].cards.remove(i);g.regions[1].cards.push(c);}restore(&mut g);settle(&mut g);assert!(g.board(&target).is_some());}}
fn bad(g:&Game,x:&Game){assert!(Game::from_persisted(&serde_json::to_string(x).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(g);r.game=x.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn jc097_pending_and_frame_corruption_rejected(){let(g,_,target)=revealed(2);for n in 0..6{let mut x=g.clone();let p=x.pending.as_mut().unwrap();let ChoiceResolution::Declare{declaration:d,..}=&mut p.resolution else{panic!()};match n{0=>p.choice.options.clear(),1=>d.source.card.definition="JC125".into(),2=>x.effects.push_back(Effect::Declare{declaration:d.clone()}),_=>{let crate::rules::Op::JC097Raid{observation:Some(o)}=&mut d.ability.ops[0]else{panic!()};match n{3=>o.corpses.push(o.corpses[0].clone()),4=>o.corpses[0].owner=1,_=>o.turn+=1}}}bad(&g,&x);}let mut g=g;choose(&mut g,vec![target]);let mut x=g.clone();x.stack.last_mut().unwrap().frame.as_mut().unwrap().steps.clear();bad(&g,&x);}
#[test]fn jc097_wrong_seat_extra_fields_and_repeated_choice(){let(mut g,_,target)=revealed(1);let a=Action{choice_id:Some(g.pending.as_ref().unwrap().choice.id.clone()),selected:Some(vec![target]),..Action::new("choose")};reject(&mut g,1,a.clone());reject(&mut g,0,Action{amount:Some(99),..a.clone()});act(&mut g,0,a.clone());reject(&mut g,0,a);settle(&mut g);}
#[test]fn jc097_counts_current_controller_grave_and_same_region_targets(){let mut g=game();let id=field(&mut g,b::ID,0);g.board_mut(&id).unwrap().controller=1;grave(&mut g,"JC125",0);grave(&mut g,"JC125",1);grave(&mut g,"JC125",1);let c=g.board(&id).unwrap().1.clone();g.emit_event(1,g.source_snapshot(&c,Some(0)),crate::rules::Event::Reveal);g.drive().unwrap();let p=g.pending.as_ref().unwrap();assert_eq!(p.seat,1);let ChoiceResolution::Declare{declaration:d,..}=&p.resolution else{panic!()};let crate::rules::Op::JC097Raid{observation:Some(o)}=&d.ability.ops[0]else{panic!()};assert_eq!(o.corpses.len(),2);restore(&mut g);}
use crate::{catalog,abi112_review_play_tests::Trace};
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert!(!d.changed&&d.journal.is_empty());assert_eq!(d.state,s["expected"]["state"]);s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn construct(seed:u64)->Game{use crate::deck;let mut d=deck::preset("watchers").unwrap();d.id="jc097-natural".into();d.society_id=None;d.core_card_id=None;d.cards=[(b::ID,3),("BQ088",3),("BQ092",3),("JC125",41)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if [b::ID,"BQ088"].contains(&c.id.as_str()){c.supported=true;}}let d=deck::validate_with_cards(d,&cards).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("jc097".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
fn initial_choice(g:&Game)->Vec<String>{let p=g.pending.as_ref().unwrap();let mut opts=p.choice.options.iter().collect::<Vec<_>>();opts.sort_by_key(|o|g.players[p.seat].hand.iter().any(|c|c.id==o.id&&[b::ID,"BQ088","BQ092"].contains(&c.definition.as_str())));opts.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()}
fn natural()->serde_json::Value{let seed=(1..10000).find(|seed|{let mut g=construct(*seed);for _ in 0..40{if g.pending.is_some(){let ids=initial_choice(&g);choose(&mut g,ids);}else if g.legal_actions(0).iter().any(|a|a.action.kind=="asset"){break;}else{let Some(s)=(0..4).find(|s|g.legal_actions(*s).iter().any(|a|a.action.kind=="pass"))else{return false;};g.apply(s,Action::new("pass")).unwrap();}}[b::ID,"BQ088","BQ092"].iter().all(|id|g.players[0].hand.iter().any(|c|&c.definition==id))&&g.players[0].deck.first().is_some_and(|c|c.definition=="JC125")}).expect("legal seed");let g=construct(seed);let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"jc097-natural-fifty-mill-conceal-reveal-raid".into(),881);let(mut milled,mut concealed,mut revealed,mut raid)=(false,false,false,false);for _ in 0..1800{if let Some(p)=t.room.game.pending.clone(){if matches!(&p.resolution,ChoiceResolution::Forecast{..}|ChoiceResolution::Frame{choice:FrameChoice::Forecast{..},..}){let top=p.choice.options.iter().map(|o|o.id.clone()).collect();t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(top),bottom:Some(vec![]),..Action::new("choose")});continue;}let ids=if matches!(&p.resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==b::KEY){raid=true;vec![p.choice.options[0].id.clone()]}else{initial_choice(&t.room.game)};t.choose(ids);continue;}if raid&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let a=if revealed{None}else if !milled&&!g.players[0].assets.is_empty(){legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::bq088::KEY)&&a.action.option.as_deref()==Some("generate"))}else if milled&&g.players[0].assets.len()>=4{legal.iter().find(|a|a.action.kind==if concealed{"reveal"}else{"conceal"}&&a.action.card_id.as_ref().is_some_and(|id|if concealed{g.board(id).is_some_and(|(_,c)|c.definition==b::ID)}else{g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==b::ID)}))}else{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition!=b::ID&&(milled||c.definition=="BQ092"))))};if let Some(a)=a{if a.action.ability_id.as_deref()==Some(crate::bq088::KEY){milled=true;}if a.action.kind=="conceal"{concealed=true;}if a.action.kind=="reveal"{revealed=true;}t.action(0,a.action.clone());}else{t.pass();}}assert!(milled&&concealed&&revealed&&raid,"seed={seed} milled={milled} concealed={concealed} revealed={revealed} raid={raid}");let mut v=t.value();v["construction"]=serde_json::json!({"seed":seed,"deck":deck,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)}
#[test]fn jc097_native_natural_export(){let cases=vec![natural()];let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/jc097.rs",include_bytes!("jc097.rs").as_slice()),("rust-game/src/jc097_tests.rs",include_bytes!("jc097_tests.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("JC097_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

#[test]fn jc097_foreign_raid_program_and_missing_play_frame_rejected(){let(mut g,_,target)=revealed(2);choose(&mut g,vec![target]);let mut x=g.clone();let f=x.stack.last_mut().unwrap().frame.as_mut().unwrap();f.ability_key="raid-1".into();f.steps=vec![Step{context:0,op:crate::rules::Op::DamageTarget{slot:0,amount:1}}];bad(&g,&x);let mut g=game();fund(&mut g,0,"JC125",3);let id=field(&mut g,b::ID,0);let c=g.hide_in_place_successor(&id).unwrap();act(&mut g,0,Action{card_id:Some(c.id),..Action::new("reveal")});let mut x=g.clone();x.stack.last_mut().unwrap().frame=None;bad(&g,&x);}
